"use client";

import { useTutorial } from "@/components/dashboard-tutorial";
import Quotations from "@/components/quotations";
import CommercialWeeks from "@/components/commercial-weeks";
import { type CommercialWeek, shortWeekDate } from "@/lib/commercial-weeks";
import MonthlyClose from "@/components/monthly-close";
import RecordHistory from "@/components/record-history";
import RecordTrash from "@/components/record-trash";
import Link from "next/link";
import InstructorRegister from "@/components/instructor-register";
import WorkspaceBanner from "@/components/workspace-banner";
import CertificateFields from "@/components/certificate-fields";
import ServiceCourses from "@/components/service-courses";
import ServiceFields from "@/components/service-fields";
import CompanyFooter from "@/components/company-footer";
import SctrCard from "@/components/sctr-card";
import InstructorCard from "@/components/instructor-card";
import MonthlySummary from "@/components/monthly-summary";
import ThemeToggle from "@/components/theme-toggle";
import { type Meta, type Service, serviceDays, serviceCourses, serviceInstructors, certificateCourses, type CertificateSale } from "@/lib/ui-types";
import { dayModality, modalityLabel } from "@/lib/class-modality";
import { classHours, durationLabel } from "@/lib/class-hours";
import Brand from "@/components/brand";

import { type CSSProperties, FormEvent, useCallback, useEffect, useRef, useState } from "react";
import { format, getDaysInMonth } from "date-fns";
import { es } from "date-fns/locale";
import { Bar, BarChart, Cell, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { LayoutDashboard, CalendarDays, Award, TrendingUp, Database, Search, Plus, RefreshCw, ChevronLeft, ChevronRight, X, Trash2, CheckCircle2, AlertCircle, Menu, BriefcaseBusiness, Wallet, Users, GraduationCap, Pencil, LogOut, CircleHelp, History, FileText } from "lucide-react";

type Sale = CertificateSale;
type DashboardData = { weeks?: CommercialWeek[]; reportSalespeople?: Meta[]; monthlyServices?: Service[]; totalInvoicedBilling?: number; invoicedBySalesperson?: Record<string, number>; totalUniqueCustomers?: number; billingGoal?: number; billingGoalAchieved?: boolean; totalServices?: number; totalEstimatedBilling?: number; topSalesRep?: string; bestSellingCourse?: string; bySalesperson: Record<string, number>; byWeek: Record<string, number>; weeklyMatrix: Record<string, Record<string, number>>; ranking: [string, number][] };
type Metadata = { instructors: Meta[]; courses: Meta[]; salespeople: Meta[]; locations: Meta[] };
type Tab = "quotations" | "summary" | "services" | "certificates" | "performance" | "support" | "instructors" | "history" | "trash";
const tabs = [{ id: "summary", label: "Vista general", icon: LayoutDashboard }, { id: "services", label: "Agenda de servicios", icon: CalendarDays }, { id: "quotations", label: "Cotizaciones", icon: FileText }, { id: "certificates", label: "Venta de certificados", icon: Award }, { id: "performance", label: "Rendimiento comercial", icon: TrendingUp }, { id: "instructors", label: "Registro de instructores", icon: GraduationCap }, { id: "support", label: "Base de soporte", icon: Database }, { id: "history", label: "Historial de cambios", icon: History }, { id: "trash", label: "Papelera", icon: Trash2 }] as const;
const statuses: Record<string, string> = { SCHEDULED: "Programado", EXECUTED: "Ejecutado", INVOICED: "Facturado" };
const money = (value: number | string) => new Intl.NumberFormat("es-PE", { style: "currency", currency: "PEN" }).format(Number(value));
const dateLabel = (value: string) => format(new Date(value), "dd MMM", { locale: es });
const emptyDashboard: DashboardData = { bySalesperson: {}, byWeek: {}, weeklyMatrix: {}, ranking: [] };
class RequestError extends Error { constructor(message: string, public data: { code?: string; matches?: { id: string; name: string; date: string; amount: string }[] }) { super(message); } }
async function request<T>(url: string, options?: RequestInit): Promise<T> {
  const response = await fetch(url, options);
  if (response.status === 401) { window.location.assign("/login"); throw new Error("Tu sesión expiró. Inicia sesión nuevamente."); }
  const data = await response.json().catch(() => null);
  if (!response.ok) throw new RequestError(typeof data?.error === "string" ? data.error : data?.message || "No se pudo completar la operación. Inténtalo nuevamente.", data ?? {});
  return data as T;
}
const post = (body: unknown): RequestInit => ({ method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });

export default function Dashboard() {
  const { active: tutorial, start: startTutorial } = useTutorial();
  const [tab, setTab] = useState<Tab>("summary");
  const [isAdmin, setIsAdmin] = useState(false);
  const [assignedRep, setAssignedRep] = useState<Meta | null>(null);
  const [period, setPeriod] = useState(() => ({ month: new Date().getMonth() + 1, year: new Date().getFullYear() }));
  const [services, setServices] = useState<Service[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [dashboard, setDashboard] = useState<DashboardData>(emptyDashboard);
  const [meta, setMeta] = useState<Metadata>({ instructors: [], courses: [], salespeople: [], locations: [] });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [notice, setNotice] = useState<{ text: string; error?: boolean } | null>(null);
  const [query, setQuery] = useState("");
  const [rep, setRep] = useState("");
  const [status, setStatus] = useState("");
  const [mobileNav, setMobileNav] = useState(false);
  const [collapsed, setCollapsed] = useState(false);
  const dragStart = useRef(0);
  useEffect(() => { try { setCollapsed(localStorage.getItem("consitec-sidebar") === "compact"); } catch {} }, []);
  const collapseSidebar = (value: boolean) => { setCollapsed(value); try { localStorage.setItem("consitec-sidebar", value ? "compact" : "expanded"); } catch {} };
  const swipeSidebar = (delta: number) => { if (Math.abs(delta) < 30) return; if (window.innerWidth <= 760) setMobileNav(delta > 0); else collapseSidebar(delta < 0); };
  const [modal, setModal] = useState<"service" | "sale" | null>(null);
  const [editingSale, setEditingSale] = useState<Sale | null>(null);
  const [editingService, setEditingService] = useState<Service | null>(null);
  const tutorialDemo = useRef(false);
  useEffect(() => {
    if (tutorial && tutorial.tab !== "users") {
      setTab(tutorial.tab as Tab); setQuery(""); setRep(""); setStatus(""); setSelectedDay(null);
      setMobileNav(false);
      if (tutorial.form) { tutorialDemo.current = true; setEditingService(null); setEditingSale(null); setModal(tutorial.form); }
      else { setModal(null); tutorialDemo.current = false; }
    } else if (!tutorial && tutorialDemo.current) { setModal(null); tutorialDemo.current = false; }
  }, [tutorial]);
  const [colorDrafts, setColorDrafts] = useState<Record<string, string>>({});
  const [colorSaving, setColorSaving] = useState("");
  const editingRecord = editingSale || editingService;
  const commercialColor = (name: string) => {
    const commercial = meta.salespeople.find(item => item.name === name);
    return commercial ? colorDrafts[commercial.id] || commercial.color || "#234eaa" : "#234eaa";
  };
  async function saveColor(id: string) {
    if (colorSaving || !colorDrafts[id]) return;
    setColorSaving(id);
    try {
      const updated = await request<Meta>(`/api/metadata/salespeople/${id}`, { ...post({ color: colorDrafts[id] }), method: "PATCH" });
      setMeta(previous => ({ ...previous, salespeople: previous.salespeople.map(item => item.id === id ? updated : item) }));
      setColorDrafts(previous => { const next = { ...previous }; delete next[id]; return next; });
      announce("Color guardado para todo el equipo.");
    } catch (err) { announce(err instanceof Error ? err.message : "No se pudo guardar el color.", true); }
    finally { setColorSaving(""); }
  }
  const [selectedDay, setSelectedDay] = useState<number | null>(null);
  const [busy, setBusy] = useState(false);
  const [pendingDelete, setPendingDelete] = useState<{ url: string; label: string } | null>(null);
  const loadVersion = useRef(0);
  const announce = (text: string, error = false) => setNotice({ text, error });
  const load = useCallback(async () => {
    const version = ++loadVersion.current;
    setLoading(true); setError("");
    try {
      const q = `month=${period.month}&year=${period.year}`;
      const [s, c, d, instructors, courses, user, locations] = await Promise.all([
        request<Service[]>(`/api/services?${q}`), request<Sale[]>(`/api/certificate-sales?${q}`), request<DashboardData>(`/api/dashboard?${q}`),
        request<Meta[]>("/api/metadata/instructors"), request<Meta[]>("/api/metadata/courses"), request<{ role: string; salesperson: Meta | null }>("/api/auth/me"), request<Meta[]>("/api/metadata/locations")
      ]);
      if (version !== loadVersion.current) return;
      setServices(s); setSales(c); setDashboard(d); setIsAdmin(user.role === "ADMIN"); setAssignedRep(user.salesperson); setMeta({ instructors, courses, salespeople: d.reportSalespeople ?? [], locations });
    } catch (err) { if (version === loadVersion.current) setError(err instanceof Error ? err.message : "No se pudieron cargar los datos."); }
    finally { if (version === loadVersion.current) setLoading(false); }
  }, [period]);
  useEffect(() => { const versionRef = loadVersion; void load(); return () => { versionRef.current++; }; }, [load]);
  useEffect(() => { if (notice) { const timer = setTimeout(() => setNotice(null), 6000); return () => clearTimeout(timer); } }, [notice]);
  useEffect(() => { setSelectedDay(null); }, [period]);
  const search = query.trim().toLocaleLowerCase("es");
  const visibleServices = services.filter(s => (!rep || s.salesperson.id === rep) && (!status || s.status === status) && (!search || [s.company, ...serviceCourses(s).map(c => c.name), s.salesperson?.name].some(v => v?.toLocaleLowerCase("es").includes(search))));
  const visibleSales = sales.filter(s => (!rep || s.salesperson.id === rep) && (!status || s.status === status) && (!search || [s.customerName, ...certificateCourses(s).map(c=>c.name), s.correlativeCode, s.certificateKind==="INSPECTION"?"Inspección":"Operador", s.salesperson?.name].some(v => v?.toLocaleLowerCase("es").includes(search))));
  const currentDate = new Date(period.year, period.month - 1, 1);
  const periodLabel = format(currentDate, "MMMM yyyy", { locale: es });
  const days = getDaysInMonth(currentDate);
  const leadingDays = (currentDate.getDay() + 6) % 7;
  const changeMonth = (delta: number) => { const date = new Date(period.year, period.month - 1 + delta, 1); setPeriod({ month: date.getMonth() + 1, year: date.getFullYear() }); };
  const [duplicate, setDuplicate] = useState<{ url: string; options: RequestInit; matches: { id: string; name: string; date: string; amount: string }[] } | null>(null);
  async function submitRecord(url: string, options: RequestInit) {
    try { await request(url, options); return true; } catch (err) { if (err instanceof RequestError && err.data.code === "POSSIBLE_DUPLICATE") { setDuplicate({ url, options, matches: err.data.matches ?? [] }); return false; } throw err; }
  }
  async function saveRecord(e: FormEvent<HTMLFormElement>) {
    e.preventDefault(); if (busy || tutorial) return;
    const formData = new FormData(e.currentTarget);
    const values = Object.fromEntries(formData);
    const amount = Number(values.amount);
    if (!Number.isFinite(amount) || amount <= 0) return announce("Ingresa un importe mayor a cero.", true);
    setBusy(true);
    try {
      if (modal === "service") {
        if (!formData.getAll("courseIds").length) throw new Error("Selecciona al menos un curso.");
        if (!await submitRecord(`/api/services${editingService ? `/${editingService.id}` : ""}`, { ...post({ ...values, sessions: JSON.parse(String(values.sessions)), courseIds: formData.getAll("courseIds"), amount, instructorIds: formData.getAll("instructorIds"), locationId: values.locationId || null, certificatesOnly: values.certificatesOnly === "on" }), method: editingService ? "PATCH" : "POST" })) return;
      } else {
        if (!formData.getAll("courseIds").length) throw new Error("Selecciona al menos un curso.");
        if (!await submitRecord(`/api/certificate-sales${editingSale ? `/${editingSale.id}` : ""}`, { ...post({ ...values, courseIds:formData.getAll("courseIds"), amount, saleDate: `${values.saleDate}T09:00:00.000Z` }), method: editingSale ? "PATCH" : "POST" })) return;
      }
      setModal(null); announce(editingRecord ? "Cambios guardados correctamente." : "Registro guardado correctamente."); await load();
    } catch (err) { announce(err instanceof Error ? err.message : "No se pudo guardar el registro.", true); }
    finally { setBusy(false); }
  }
  async function deleteRecord() {
    if (!pendingDelete || busy) return;
    setBusy(true);
    try { await request(pendingDelete.url, { method: "DELETE" }); setPendingDelete(null); announce(pendingDelete.url.startsWith("/api/metadata/") ? "Registro del catálogo eliminado." : "Registro enviado a la papelera. Puedes recuperarlo durante 7 días."); await load(); }
    catch (err) { announce(err instanceof Error ? err.message : "No se pudo eliminar.", true); }
    finally { setBusy(false); }
  }
  const openRecord = (kind: "service" | "sale") => { setEditingSale(null); setEditingService(null); setSelectedDay(null); setModal(kind); };
  const serviceCard = (s: Service, activeDate?: string) => <article key={s.id} className={`service-item ${s.certificatesOnly ? "certificate-item" : ""}`}><div className="split"><strong title={s.company}>{s.correlativeCode ? `${s.correlativeCode} · ` : ""}{s.company}</strong><div className="record-actions"><button className="icon-button" aria-label={`Editar servicio de ${s.company}`} onClick={() => { setEditingService(s); setEditingSale(null); setSelectedDay(null); setModal("service"); }}><Pencil size={14} /></button><button className="icon-button danger" aria-label={`Eliminar servicio de ${s.company}`} onClick={() => { setSelectedDay(null); setPendingDelete({ url: `/api/services/${s.id}`, label: s.company }); }}><Trash2 size={14} /></button></div></div><span>{serviceCourses(s).map(c => c.name).join(" · ") || "Sin curso"}</span><small>{serviceInstructors(s).map(i=>i.name).join(" · ") || "Sin instructor"}{s.travelMode === "PLANE" ? " · Avión" : s.travelMode === "BUS" ? " · Bus" : ""}{serviceDays(s).length > 1 ? ` · ${serviceDays(s).length} servicios · importe único` : ""}</small>{s.modality && <small>{modalityLabel(activeDate ? dayModality(s.modality, s.dates?.find(d => d.date.slice(0,10) === activeDate)?.modality) : s.modality)}</small>}{s.dates?.filter(d => (!activeDate || d.date.slice(0,10) === activeDate) && (s.modality === 'MIXED' || (d.startTime && d.endTime))).map(d => { const hours = d.startTime && d.endTime ? classHours(d.startTime, d.endTime) : null; return <small key={d.date}>{dateLabel(d.date)}{s.modality === 'MIXED' ? ` · ${modalityLabel(dayModality(s.modality,d.modality))}` : ''}{d.startTime && d.endTime ? ` · ${d.startTime}–${d.endTime}` : ''}{hours ? ` · ${durationLabel(hours.instructionalMinutes)} de clase${hours.breakMinutes ? ' (descanso descontado)' : ''}` : ''}</small>; })}<div className="split"><small>{s.salesperson?.name}</small><b>{money(s.amount)}</b></div><span className={`status status-${s.status.toLowerCase()}`}>{statuses[s.status] || s.status}</span></article>;

  const banner = {
    summary: {kicker:'TU EQUIPO. TU AVANCE.',title:assignedRep?.name?`Vamos por más, ${assignedRep.name}`:'Cada servicio cuenta',description:'Organiza tus clases, registra certificados y sigue tus metas en un solo lugar.'},
    services: {kicker:'FECHAS CLARAS. EQUIPO COORDINADO.',title:'Dale orden a cada jornada',description:'Coordina cursos, fechas e instructores. Cada clase aparece en tu agenda y comparte el importe del servicio.'},
    quotations: {kicker:'PROPUESTAS QUE ABREN OPORTUNIDADES.',title:'El siguiente servicio empieza aquí',description:'Prepara tu cotización, adjunta el PDF y acompaña al cliente hasta convertir su propuesta en un servicio.'},
    certificates: {kicker:'CADA CERTIFICADO, UNA VENTA BIEN REGISTRADA.',title:'Certifica el avance de tus clientes',description:'Registra certificados de operador o inspección, reúne sus cursos y mantén claros sus importes y correlativos.'},
    performance: {kicker:'EL ESFUERZO SE VE EN LOS RESULTADOS.',title:'Haz visible el avance de tu equipo',description:'Compara semanas, consulta el ranking y revisa el resumen de cada comercial para seguir las metas del mes.'},
    instructors: {kicker:'CADA CLASE. CADA INSTRUCTOR.',title:'Toda la experiencia, bien organizada',description:'Consulta jornadas y horas por instructor, confirma tus registros y prepara el Excel que necesitas.'},
    support: {kicker:'UNA BUENA OPERACIÓN EMPIEZA CON BUENA INFORMACIÓN.',title:'La base de un equipo preparado',description:isAdmin?'Mantén al día instructores, cursos, ubicaciones y comerciales para que cada registro tenga la información correcta.':'Mantén al día instructores, cursos y ubicaciones para que cada registro tenga la información correcta.'},
    history: {kicker:'CLARIDAD EN CADA MOVIMIENTO.',title:'Cada cambio tiene su historia',description:isAdmin?'Consulta quién modificó los registros y revisa su antes y después. El historial reúne los cambios de todo el equipo.':'Consulta los cambios de tu comercial y tus propias acciones. Cada movimiento muestra quién lo hizo y qué cambió.'},
    trash: {kicker:'SI TE EQUIVOCASTE, PUEDES RECUPERARLO.',title:'Una segunda oportunidad para tus registros',description:'Revisa servicios y ventas eliminados. Tienes siete días para recuperarlos con sus fechas, importe y estado originales.'}
  }[tab];
  const goTo=(target:Tab)=>{setTab(target);setQuery('');setRep('');setStatus('');};
  const focusSection=(selector:string)=>{const target=document.querySelector<HTMLElement>(selector);target?.scrollIntoView({behavior:'smooth',block:'center'});if(target?.matches('input,select,button'))target.focus({preventScroll:true});};
  const bannerActions = tab==='summary'?<><button className="btn" disabled={loading} onClick={()=>openRecord('service')}><Plus size={16}/>Registrar servicio</button><button className="btn secondary" disabled={loading} onClick={()=>{goTo('certificates');openRecord('sale');}}><Award size={16}/>Vender certificados</button></>:tab==='services'?<><button className="btn" disabled={loading} onClick={()=>openRecord('service')}><Plus size={16}/>Registrar servicio</button><button className="btn secondary" onClick={()=>goTo('instructors')}><GraduationCap size={16}/>Ver instructores</button></>:tab==='quotations'?<><button className="btn" disabled={loading} onClick={()=>document.querySelector<HTMLButtonElement>('[data-tour="new-quotation"]')?.click()}><Plus size={16}/>Nueva cotización</button><button className="btn secondary" onClick={()=>goTo('services')}><CalendarDays size={16}/>Ver agenda</button></>:tab==='certificates'?<><button className="btn" disabled={loading} onClick={()=>openRecord('sale')}><Plus size={16}/>Nueva venta</button><button className="btn secondary" onClick={()=>goTo('performance')}><TrendingUp size={16}/>Ver rendimiento</button></>:tab==='performance'?<><button className="btn" onClick={()=>focusSection('.monthly-summary')}><Users size={16}/>Resumen por comercial</button><button className="btn secondary" onClick={()=>{const editor=document.querySelector<HTMLDetailsElement>('.week-editor');if(isAdmin&&editor)editor.open=true;focusSection('.commercial-weeks');}}><CalendarDays size={16}/>{isAdmin?'Configurar semanas':'Consultar semanas'}</button></>:tab==='instructors'?<><button className="btn" onClick={()=>focusSection('.register-filters select')}><Search size={16}/>Ir a los filtros</button><button className="btn secondary" onClick={()=>goTo('services')}><CalendarDays size={16}/>Ver agenda</button></>:tab==='support'?<><button className="btn" onClick={()=>focusSection('.instructor-card')}><GraduationCap size={16}/>Fichas de instructores</button><button className="btn secondary" onClick={()=>focusSection('[data-tour="support-courses"]')}><Database size={16}/>Catálogo de cursos</button></>:tab==='history'?<><button className="btn" onClick={()=>focusSection('.history-panel input')}><Search size={16}/>Buscar un cambio</button><button className="btn secondary" onClick={()=>goTo('trash')}><Trash2 size={16}/>Abrir papelera</button></>:<><button className="btn" onClick={()=>focusSection('.trash-panel')}><History size={16}/>Revisar registros</button><button className="btn secondary" onClick={()=>goTo('history')}><History size={16}/>Ver historial</button></>;

  return <div data-tutorial={!!tutorial} className={`workspace-shell ${collapsed ? "sidebar-collapsed" : ""}`}>
    <aside className={`sidebar ${mobileNav ? "is-open" : ""}`} onTouchStart={e => { dragStart.current = e.changedTouches[0].clientX; }} onTouchEnd={e => swipeSidebar(e.changedTouches[0].clientX - dragStart.current)}><div className="sidebar-content"><div className="sidebar-brand"><Brand href="/dashboard" /></div><button type="button" className="sidebar-toggle icon-button" aria-label={collapsed ? "Expandir barra lateral" : "Contraer barra lateral"} aria-expanded={!collapsed} onClick={() => collapseSidebar(!collapsed)}>{collapsed ? <ChevronRight size={20} /> : <ChevronLeft size={20} />}</button><div className="nav-caption">ESPACIO DE TRABAJO</div><nav aria-label="Navegación principal">{tabs.map(item => <button key={item.id} className={`nav-item ${tab === item.id ? "active" : ""}`} aria-label={item.label} title={item.label} aria-current={tab === item.id ? "page" : undefined} onClick={() => { setTab(item.id); setMobileNav(false); setQuery(""); setRep(""); setStatus(""); }}><item.icon size={19} /><span className="nav-label">{item.label}</span></button>)}{isAdmin && <Link className="nav-item" href="/dashboard/users" aria-label="Usuarios" title="Usuarios"><Users size={19} /><span className="nav-label">Usuarios</span></Link>}</nav><div className="sidebar-note"><span className="live-dot" />Tu operación, en un solo lugar<p>Servicios, certificados y equipo comercial.</p></div></div><div className="sidebar-bottom"><div className="sidebar-footer"><span className="avatar">CO</span><div>{assignedRep?.name || "Equipo Consitec"}<small>{isAdmin?"Administración":"Equipo comercial"}</small></div></div><button className="nav-item logout-button" aria-label="Cerrar sesión" title="Cerrar sesión" onClick={async () => { await fetch("/api/auth/logout", { method: "POST" }); window.location.assign("/login"); }}><LogOut size={19} /><span className="nav-label">Cerrar sesión</span></button></div><div className="sidebar-drag" role="separator" aria-label="Ajustar barra lateral" aria-orientation="vertical" tabIndex={0} onKeyDown={e => { if (e.key === "ArrowLeft") collapseSidebar(true); if (e.key === "ArrowRight") collapseSidebar(false); }} onPointerDown={e => { dragStart.current = e.clientX; e.currentTarget.setPointerCapture(e.pointerId); }} onPointerUp={e => { swipeSidebar(e.clientX - dragStart.current); e.currentTarget.releasePointerCapture(e.pointerId); }} /></aside>
    {mobileNav && <button className="nav-backdrop" aria-label="Cerrar navegación" onClick={() => setMobileNav(false)} />}
    <main className="main-content"><header className="topbar"><div className="topbar-left"><button className="icon-button mobile-menu" aria-label="Abrir navegación" onClick={() => setMobileNav(true)}><Menu size={22} /></button><span>Panel comercial <span className="breadcrumb">/ {tabs.find(t => t.id === tab)?.label}</span></span></div><div className="topbar-actions"><span className="access-badge">{isAdmin?"Administrador":"Vendedor"}</span><button className="refresh-button" aria-label="Ver tutorial" title="Ver tutorial" data-tour="replay" onClick={startTutorial}><CircleHelp size={18} />Ver tutorial</button><ThemeToggle /><button className="refresh-button" data-tour="refresh" disabled={loading} onClick={() => void load()}><RefreshCw size={16} className={loading ? "spin" : ""} />Actualizar</button></div></header>
      <div className="page-content"><div className="page-heading"><div><div className="eyebrow">CONSITEC · OPERACIONES</div><h1>{tabs.find(t => t.id === tab)?.label}</h1><p>{tab === "quotations" ? "Prepara propuestas, adjunta tu PDF y convierte las aceptadas en servicios." : tab === "history" ? "Consulta quién cambió cada registro y compara sus datos." : tab === "trash" ? "Recupera servicios y ventas dentro de los siete días posteriores a su eliminación." : tab === "summary" ? "Una mirada clara a tu actividad comercial del mes." : tab === "services" ? "Organiza los servicios y consulta cada jornada." : tab === "certificates" ? "Gestiona tus ventas y consulta sus importes." : tab === "performance" ? "Consulta el avance semanal de tu equipo." : tab === "instructors" ? "Consulta las clases por instructor y descarga tu registro." : "Administra los datos que sostienen tu operación."}</p></div>{(["summary","services","certificates"] as Tab[]).includes(tab) && <button className="btn" onClick={() => openRecord(tab === "certificates" ? "sale" : "service")}><Plus size={17} />{tab === "certificates" ? "Nueva venta" : "Nuevo servicio"}</button>}</div>
      {tab !== "history" && tab !== "trash" && <div className="period-toolbar"><div className="period-picker"><button className="icon-button" aria-label="Mes anterior" onClick={() => changeMonth(-1)}><ChevronLeft size={18} /></button><CalendarDays size={18} /><select aria-label="Mes" value={period.month} onChange={e => setPeriod({ ...period, month: Number(e.target.value) })}>{Array.from({ length: 12 }, (_, i) => <option key={i} value={i + 1}>{format(new Date(2026, i, 1), "MMMM", { locale: es })}</option>)}</select><select aria-label="Año" value={period.year} onChange={e => setPeriod({ ...period, year: Number(e.target.value) })}>{Array.from(new Set([period.year, ...Array.from({ length: 11 }, (_, i) => new Date().getFullYear() - 5 + i)])).sort((a, b) => a - b).map(y => <option key={y}>{y}</option>)}</select><button className="icon-button" aria-label="Mes siguiente" onClick={() => changeMonth(1)}><ChevronRight size={18} /></button></div><span className="period-hint">{loading ? "Cargando información…" : `${dashboard.totalServices ?? 0} servicios · ${sales.length} ventas de certificados · ${dashboard.totalUniqueCustomers ?? 0} clientes únicos`}</span></div>}
      {error && <div className="error-banner" role="alert"><AlertCircle size={18} /><span>{error}</span><button onClick={() => void load()}>Reintentar</button></div>}
      <WorkspaceBanner variant={tab} {...banner} icon={tabs.find(t=>t.id===tab)!.icon} actions={bannerActions} meta={tab==="history"||tab==="trash"?undefined:tab==="quotations"?"Propuestas de todos los meses":tab==="support"?"Catálogos compartidos":periodLabel}/>
      <div aria-busy={loading} className={loading ? "content-area is-loading" : "content-area"}>
      {tab === "summary" && <><div className="metric-grid billing-metrics">{[{ label: "Servicios del mes", value: dashboard.totalServices ?? 0, icon: BriefcaseBusiness, note: "Actividad registrada", tone: "blue" }, { label: "Facturación estimada", value: money(dashboard.totalEstimatedBilling ?? 0), icon: Wallet, note: "Importes de servicios", tone: "orange" }, { label: "Total facturado", value: money(dashboard.totalInvoicedBilling ?? 0), icon: Wallet, note: "Servicios y certificados de empresas", tone: "green" }, { label: "Comercial destacado", value: dashboard.topSalesRep || "—", icon: Users, note: "Por cantidad de servicios", tone: "purple" }, { label: "Curso más vendido", value: dashboard.bestSellingCourse || "—", icon: GraduationCap, note: "Durante el mes seleccionado", tone: "green" }].map(m => <div className="metric-card" key={m.label}><div className="split"><span>{m.label}</span><div className={`metric-icon ${m.tone}`}><m.icon size={21} /></div></div><div className="metric-value">{m.value}</div><small>{m.note}</small></div>)}</div><div className="chart-grid"><Chart title="Actividad por comercial" subtitle="Servicios registrados en el mes" data={Object.entries(dashboard.bySalesperson).map(([name, value]) => ({ name, value, color: commercialColor(name) }))} color="#234eaa" /><Chart title="Distribución semanal" subtitle={dashboard.weeks?.map(w => `${w.name}: ${shortWeekDate(w.startDate)}–${shortWeekDate(w.endDate)}`).join(" · ") || "Períodos semanales del mes"} data={Object.entries(dashboard.byWeek).map(([name, value], i) => ({ name: dashboard.weeks?.[i]?.name || `Semana ${i + 1}`, value }))} color="#f28a36" /></div><div className="bottom-grid"><section className="panel"><div className="section-heading"><div><h2>Metas del mes</h2><p>Avance mensual de servicios y facturación</p></div><TrendingUp size={20} /></div>{[45, 70].map(target => <div className="goal" key={target}><div className="split"><strong>Bono {target}</strong><span>{dashboard.totalServices ?? 0} / {target} <small>servicios</small></span></div><progress max={target} value={Math.min(dashboard.totalServices ?? 0, target)} /><small>{(dashboard.totalServices ?? 0) > target ? "Bono activado" : `Faltan ${target + 1 - (dashboard.totalServices ?? 0)} servicios para activar el bono`}</small></div>)}<div className="goal"><div className="split"><strong>Meta de facturación</strong><span>{money(dashboard.totalInvoicedBilling ?? 0)} / {money(dashboard.billingGoal ?? 200000)}</span></div><progress aria-label="Meta de facturación" max={dashboard.billingGoal ?? 200000} value={Math.min(dashboard.totalInvoicedBilling ?? 0, dashboard.billingGoal ?? 200000)} /><small>{dashboard.billingGoalAchieved ? "Meta alcanzada" : `Faltan ${money(Math.max(0, (dashboard.billingGoal ?? 200000) - (dashboard.totalInvoicedBilling ?? 0)))}`} · Solo estado Facturado</small></div></section><section className="panel"><div className="section-heading"><div><h2>Próximos servicios</h2><p>Programados en {periodLabel}</p></div><button className="text-button" onClick={() => setTab("services")}>Ver agenda →</button></div>{services.filter(s => s.status === "SCHEDULED").slice(0, 4).map(s => <div className="upcoming-item" key={s.id}><span className="date-chip">{dateLabel(s.serviceDate)}</span><div><strong>{s.company}</strong><small>{serviceCourses(s).map(c=>c.name).join(" · ")}</small></div><b>{money(s.amount)}</b></div>)}{!services.some(s => s.status === "SCHEDULED") && <Empty text="No hay servicios programados este mes." />}</section></div></>}
      {(tab === "services" || tab === "certificates") && <div className="filter-bar"><label className="search-box"><Search size={17} /><input aria-label="Buscar cliente, curso o comercial" placeholder="Buscar cliente, curso o comercial…" value={query} onChange={e => setQuery(e.target.value)} /></label><select aria-label="Filtrar por comercial" value={rep} onChange={e => setRep(e.target.value)}><option value="">Todos los comerciales</option>{meta.salespeople.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}</select><select aria-label="Filtrar por estado" value={status} onChange={e => setStatus(e.target.value)}><option value="">Todos los estados</option>{Object.entries(statuses).map(([k, v]) => <option key={k} value={k}>{v}</option>)}</select>{(query || rep || status) && <button className="text-button" onClick={() => { setQuery(""); setRep(""); setStatus(""); }}>Limpiar</button>}</div>}
      {tab === "services" && <section className="panel calendar-panel"><div className="section-heading"><div><h2 className="capitalize">{periodLabel}</h2><p>{visibleServices.length} servicios coinciden con tus filtros</p></div><span className="legend"><i />Servicio <i className="orange-dot" />Certificado</span></div><div className="calendar-scroll"><div className="calendar"><div className="weekdays">{["Lun", "Mar", "Mié", "Jue", "Vie", "Sáb", "Dom"].map(d => <span key={d}>{d}</span>)}</div><div className="calendar-days">{Array.from({ length: leadingDays }, (_, i) => <div className="calendar-day outside" key={`blank-${i}`} />)}{Array.from({ length: days }, (_, i) => { const day = i + 1; const items = visibleServices.filter(s => serviceDays(s).includes(format(new Date(period.year, period.month - 1, day), "yyyy-MM-dd"))); const today = new Date(); const isToday = today.getDate() === day && today.getMonth() + 1 === period.month && today.getFullYear() === period.year; return <div className={`calendar-day ${isToday ? "today" : ""}`} key={day}><button className="day-number" aria-label={`Ver servicios del ${day} de ${periodLabel}`} onClick={() => setSelectedDay(day)}>{day}{items.length > 0 && <small>{items.length}</small>}</button>{items.slice(0, 2).map(s => serviceCard(s, format(new Date(period.year, period.month - 1, day), "yyyy-MM-dd")))}{items.length > 2 && <button className="text-button" onClick={() => setSelectedDay(day)}>+{items.length - 2} más</button>}</div>; })}</div></div></div>{!visibleServices.length && <Empty text="No hay servicios para esta selección." action="Registrar servicio" onAction={() => openRecord("service")} />}</section>}
      {tab === "certificates" && <><div className="sale-summary">{[{ label: "Personas naturales", value: visibleSales.filter(s => s.customerType === "NATURAL_PERSON").reduce((a, s) => a + Number(s.amount), 0) }, { label: "Empresas", value: visibleSales.filter(s => s.customerType === "COMPANY").reduce((a, s) => a + Number(s.amount), 0) }, { label: "Total de la selección", value: visibleSales.reduce((a, s) => a + Number(s.amount), 0) }].map(m => <div className="metric-card" key={m.label}><small>{m.label}</small><div className="metric-value">{money(m.value)}</div></div>)}</div><section className="panel"><div className="section-heading"><div><h2>Ventas de certificados</h2><p>{visibleSales.length} registros en la selección</p></div></div><div className="table-scroll"><table><thead><tr><th>Cliente / curso</th><th>Certificado / cliente</th><th>Comercial</th><th>Importe</th><th>Fecha</th><th>Estado</th><th><span className="sr-only">Acciones</span></th></tr></thead><tbody>{visibleSales.map(s => <tr key={s.id}><td><strong>{s.correlativeCode?`${s.correlativeCode} · `:""}{s.customerName}</strong><small>{certificateCourses(s).map(c=>c.name).join(" · ")}</small></td><td><span className={`certificate-kind ${s.certificateKind==="INSPECTION"?"inspection":""}`}>{s.certificateKind==="INSPECTION"?"Inspección":"Operador"}</span><small>{s.customerType === "COMPANY" ? "Empresa" : "Persona natural"}</small></td><td>{s.salesperson?.name}</td><td><b>{money(s.amount)}</b></td><td>{dateLabel(s.saleDate)}</td><td><span className={`status status-${s.status.toLowerCase()}`}>{statuses[s.status]}</span></td><td><div className="record-actions"><button className="icon-button" aria-label={`Editar venta de ${s.customerName}`} onClick={() => { setEditingSale(s); setEditingService(null); setModal("sale"); }}><Pencil size={17} /></button><button className="icon-button danger" aria-label={`Eliminar venta de ${s.customerName}`} onClick={() => setPendingDelete({ url: `/api/certificate-sales/${s.id}`, label: s.customerName })}><Trash2 size={17} /></button></div></td></tr>)}</tbody></table></div>{!visibleSales.length && <Empty text="No hay ventas para esta selección." action="Registrar venta" onAction={() => openRecord("sale")} />}</section></>}
      {tab === "performance" && <><CommercialWeeks key={`${period.year}-${period.month}`} year={period.year} month={period.month} isAdmin={isAdmin} refreshKey={loadVersion.current} onDone={load} /><div className="bottom-grid"><section className="panel"><div className="section-heading"><div><h2>Avance semanal</h2><p>El distintivo aparece al superar 5 servicios por semana.</p></div></div><div className="table-scroll"><table><thead><tr><th>Comercial</th><th>Total facturado</th>{dashboard.weeks?.map(w => <th key={w.key}>{w.name}<small>{shortWeekDate(w.startDate)}–{shortWeekDate(w.endDate)}</small></th>)}</tr></thead><tbody>{meta.salespeople.map(sp => <tr key={sp.id}><td><strong>{sp.name}</strong></td><td><b>{money(dashboard.invoicedBySalesperson?.[sp.name || ""] ?? 0)}</b></td>{dashboard.weeks?.map(w => { const count = dashboard.weeklyMatrix[sp.name || ""]?.[w.key] || 0; return <td key={w.key}><span className={count > 5 ? "count-badge achieved" : "count-badge"}>{count}{count > 5 && <CheckCircle2 size={12} />}</span></td>; })}</tr>)}</tbody></table></div>{!meta.salespeople.length && <Empty text="Agrega comerciales en la base de soporte." />}</section><section className="panel"><div className="section-heading"><div><h2>Ranking mensual</h2><p>Ordenado por cantidad de servicios</p></div><Award size={22} /></div>{dashboard.ranking.map(([name, value], i) => <div className="ranking-item" key={name}><span className={`rank ${i === 0 ? "first" : ""}`}>{i + 1}</span><div><strong>{name}</strong><progress aria-label={`Servicios de ${name}`} value={value} max={dashboard.ranking[0]?.[1] || 1} style={{ "--bar-color": commercialColor(name) } as CSSProperties} /></div><b>{value}<small>servicios</small></b></div>)}{!dashboard.ranking.length && <Empty text="El ranking aparecerá cuando registres servicios." />}
        {isAdmin && !!meta.salespeople.length && <div className="commercial-colors"><h3>Colores de comerciales</h3><p>Elige el color de cada barra y guárdalo para todo el equipo.</p>{meta.salespeople.map(sp => <form className="commercial-color-row" key={sp.id} onSubmit={e => { e.preventDefault(); void saveColor(sp.id); }}><label htmlFor={`color-${sp.id}`}>{sp.name}</label><input id={`color-${sp.id}`} aria-label={`Color de ${sp.name}`} type="color" value={commercialColor(sp.name || "")} disabled={!!colorSaving} onChange={e => setColorDrafts(previous => ({ ...previous, [sp.id]: e.target.value }))} /><button className="btn secondary" disabled={!!colorSaving || !colorDrafts[sp.id]}>{colorSaving === sp.id ? "Guardando…" : "Guardar color"}</button></form>)}</div>}
        </section><MonthlySummary services={dashboard.monthlyServices ?? services} salespeople={meta.salespeople} month={period.month} year={period.year} /></div></>}
      {tab === "instructors" && <InstructorRegister key={`${period.year}-${period.month}`} month={period.month} year={period.year} instructors={meta.instructors} courses={meta.courses} refreshToken={loadVersion.current} />}
      {tab !== "history" && tab !== "trash" && tab !== "quotations" && <MonthlyClose period={period} isAdmin={isAdmin} onDone={load} onPeriod={setPeriod} refreshKey={services} />}
      {tab === "quotations" && <Quotations courses={meta.courses} instructors={meta.instructors} locations={meta.locations} isAdmin={isAdmin} refreshKey={loadVersion.current} onConverted={() => void load()} />}
      {tab === "history" && <RecordHistory />}
      {tab === "trash" && <RecordTrash onDone={load} />}
      {tab === "support" && <div className="support-grid"><SctrCard instructors={meta.instructors} onDone={load} announce={announce} />{([{ key: "instructors", title: "Instructores", fields: ["name"] }, { key: "courses", title: "Cursos", fields: ["name"] }, { key: "salespeople", title: "Comerciales", fields: ["name"] }, { key: "locations", title: "Ubicaciones", fields: ["department", "district"] }] as const).filter(item => isAdmin || item.key !== "salespeople").map(item => item.key === "instructors" ? <InstructorCard key={item.key} items={meta.instructors} courses={meta.courses} onDone={load} announce={announce} onDelete={(id, label) => setPendingDelete({ url: `/api/metadata/instructors/${id}`, label })} /> : <SupportCard key={item.key} title={item.title} endpoint={item.key} fields={[...item.fields]} items={meta[item.key]} onDone={load} announce={announce} onDelete={(id, label) => setPendingDelete({ url: `/api/metadata/${item.key}/${id}`, label })} />)}</div>}
      </div><CompanyFooter /></div>
    </main>
    {notice && <div className={`toast ${notice.error ? "toast-error" : ""}`} role={notice.error ? "alert" : "status"}>{notice.error ? <AlertCircle size={20} /> : <CheckCircle2 size={20} />}<span>{notice.text}</span><button className="icon-button" aria-label="Cerrar notificación" onClick={() => setNotice(null)}><X size={17} /></button></div>}
    {modal && <Dialog className="record-dialog" title={editingRecord ? (modal === "service" ? "Editar servicio" : "Editar venta de certificado") : (modal === "service" ? "Nuevo servicio" : "Nueva venta de certificado")} onClose={() => { if (!busy) setModal(null); }}>
      <p className="dialog-intro">{editingRecord ? "Actualiza los datos del registro. El comercial original se conserva." : "Completa cada sección. Los campos opcionales están indicados."}</p>
      <form key={editingRecord?.id || modal} onSubmit={saveRecord}>
        {modal==='sale' ? <CertificateFields sale={editingSale} courses={meta.courses} previewCompany={!!tutorial?.target.includes('correlativeCode')}/>:<>
          <section className="record-section"><div className="record-section-title"><span>01</span><div><h3>Cliente y referencia</h3><p>Identifica el servicio.</p></div></div><div className="form-grid"><label className="full-width">Empresa / cliente<input name="company" placeholder="Nombre o razón social" maxLength={200} defaultValue={editingService?.company} required/></label><label>Código de correlativo<input name="correlativeCode" inputMode="numeric" pattern="[0-9]{4}" minLength={4} maxLength={4} defaultValue={editingService?.correlativeCode||''} placeholder="Ej. 0042" required/></label></div></section>
          <section className="record-section"><div className="record-section-title"><span>02</span><div><h3>Cursos incluidos</h3><p>Todo el alcance, en un único servicio.</p></div></div><ServiceCourses courses={meta.courses} service={editingService}/></section>
          <section className="record-section"><div className="record-section-title"><span>03</span><div><h3>Programación y equipo</h3><p>Fechas, modalidad e instructores.</p></div></div><div className="form-grid"><ServiceFields service={editingService} includeCorrelative={false} includeInvoiceDate={false} previewMixed={tutorial?.title==='Modalidad por fecha'} instructors={meta.instructors} defaultDate={format(new Date(period.year,period.month-1,selectedDay??1),'yyyy-MM-dd')}/><label>Ubicación <small>(opcional)</small><select name="locationId" defaultValue={editingService?.location?.id||''}><option value="">Sin asignar</option>{meta.locations.map(c=><option key={c.id} value={c.id}>{c.department} / {c.district}</option>)}</select></label></div></section>
        </>}
        <section className="record-section"><div className="record-section-title"><span>{modal==='sale'?'03':'04'}</span><div><h3>Importe y facturación</h3><p>Un importe total para todo el registro.</p></div></div><div className="form-grid">
          {modal==='sale'&&<label>Fecha de venta<input name="saleDate" type="date" defaultValue={editingSale?.saleDate.slice(0,10)||format(new Date(period.year,period.month-1,selectedDay??1),'yyyy-MM-dd')} required/></label>}
          <label>Fecha de facturación <small>(opcional)</small><input name="invoiceDate" type="date" defaultValue={editingRecord?.invoicedAt?.slice(0,10)||''}/><small>Al marcar Facturado se usará hoy si está vacía.</small></label>
          <label>Importe total (S/)<input name="amount" type="number" min="0.01" max="99999999.99" step="0.01" placeholder="0.00" defaultValue={editingRecord?.amount} required/></label>
          <label>Estado<select name="status" defaultValue={editingRecord?.status||'SCHEDULED'}>{Object.entries(statuses).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></label>
          {modal==='service'&&<details className="optional-fields full-width"><summary>Opciones adicionales</summary><label className="checkbox-label"><input name="certificatesOnly" type="checkbox" defaultChecked={editingService?.certificatesOnly||false}/>Solo certificados</label></details>}
        </div></section>
        <div className="assigned-commercial"><span>Comercial {editingRecord?'del registro':'asignado'}</span><strong>{editingRecord?.salesperson.name||assignedRep?.name||'Sin asignar'}</strong><small>{editingRecord?'La edición conserva el comercial original.':'Se asigna automáticamente desde tu cuenta.'}</small></div>
        {modal==='sale'&&<p className="form-note">{editingSale?'Los servicios en la agenda se editan por separado. Editar esta venta no crea nuevas copias.':'Las ventas mayores a S/700 también se agregan a la agenda. El importe no se duplica en la facturación.'}</p>}
        <div className="dialog-actions"><button type="button" className="btn secondary" disabled={busy} onClick={()=>setModal(null)}>Cancelar</button><button className="btn" disabled={busy||!meta.courses.length||(!editingRecord&&!assignedRep)}>{busy?'Guardando…':editingRecord?'Guardar cambios':modal==='sale'?'Guardar venta':'Guardar servicio'}</button></div>
        {!meta.courses.length&&<p className="form-note">Agrega al menos un curso en la base de soporte.</p>}{!editingRecord&&!assignedRep&&<p className="error-banner" role="alert">Un administrador debe asignarte un comercial en Usuarios antes de registrar ventas o servicios.</p>}
      </form>
    </Dialog>}
    {selectedDay !== null && <Dialog title={`Servicios del ${selectedDay} de ${periodLabel}`} onClose={() => setSelectedDay(null)}>{visibleServices.filter(s => serviceDays(s).includes(format(new Date(period.year, period.month - 1, selectedDay!), "yyyy-MM-dd"))).map(s => serviceCard(s, format(new Date(period.year, period.month - 1, selectedDay!), "yyyy-MM-dd")))}{!visibleServices.some(s => serviceDays(s).includes(format(new Date(period.year, period.month - 1, selectedDay!), "yyyy-MM-dd"))) && <Empty text="No hay servicios que coincidan con tus filtros este día." />}</Dialog>}
    {duplicate && <Dialog title="Posible duplicado" onClose={() => { if (!busy) setDuplicate(null); }}><p>Encontramos registros con el mismo cliente, curso y fecha. Si representan ventas diferentes, puedes continuar.</p><ul>{duplicate.matches.map(row => <li key={row.id}>{row.name} · {row.date} · S/ {row.amount}</li>)}</ul><div className="dialog-actions"><button className="btn secondary" disabled={busy} onClick={() => setDuplicate(null)}>Volver y revisar</button><button className="btn" disabled={busy} onClick={async () => { setBusy(true); try { await request(duplicate.url, { ...duplicate.options, body: JSON.stringify({ ...JSON.parse(String(duplicate.options.body)), allowDuplicate: true }) }); setDuplicate(null); setModal(null); announce("Registro guardado tras confirmar la coincidencia."); await load(); } catch (err) { announce((err as Error).message, true); } finally { setBusy(false); } }}>Guardar de todos modos</button></div></Dialog>}
    {pendingDelete && <Dialog title="Eliminar registro" onClose={() => { if (!busy) setPendingDelete(null); }}><p>Se eliminará el registro de <strong>{pendingDelete.label}</strong>. {pendingDelete.url.startsWith("/api/metadata/") ? "Solo se puede eliminar si no está vinculado a registros. Esta eliminación no se recupera desde Papelera." : "Puedes recuperarlo durante 7 días desde Papelera."}</p><div className="dialog-actions"><button className="btn secondary" disabled={busy} onClick={() => setPendingDelete(null)}>Cancelar</button><button className="btn destructive" disabled={busy} onClick={() => void deleteRecord()}>{busy ? "Eliminando…" : "Eliminar registro"}</button></div></Dialog>}
  </div>;
}
function Empty({ text, action, onAction }: { text: string; action?: string; onAction?: () => void }) { return <div className="empty-state"><CalendarDays size={27} /><p>{text}</p>{action && <button className="text-button" onClick={onAction}>{action} →</button>}</div>; }
function Chart({ title, subtitle, data, color }: { title: string; subtitle: string; data: { name: string; value: number; color?: string }[]; color: string }) { return <section className="panel"><div className="section-heading"><div><h2>{title}</h2><p>{subtitle}</p></div></div>{data.some(d => d.value > 0) ? <div className="chart-height"><ResponsiveContainer width="100%" height="100%"><BarChart data={data} margin={{ left: -20, right: 8, top: 10, bottom: 16 }}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e9edf4" /><XAxis dataKey="name" tick={{ fontSize: 11 }} axisLine={false} tickLine={false} /><YAxis allowDecimals={false} tick={{ fontSize: 11 }} axisLine={false} tickLine={false} /><Tooltip wrapperStyle={{maxWidth:180}} cursor={{ fill: "var(--chart-hover)" }} formatter={value => [value, "Servicios"]} contentStyle={{ maxWidth:180, whiteSpace:"normal", overflowWrap:"anywhere", borderRadius: 12, border: "1px solid #e2e8f0" }} /><Bar dataKey="value" activeBar={{ stroke: "var(--blue)", strokeWidth: 1.2 }} fill={color} radius={[6, 6, 0, 0]} maxBarSize={45}>{data.map(item => <Cell key={item.name} fill={item.color || color} />)}</Bar></BarChart></ResponsiveContainer></div> : <Empty text="Los gráficos aparecerán al registrar servicios." />}</section>; }
function Dialog({ title, onClose, children, className = "" }: { title: string; onClose: () => void; children: React.ReactNode; className?: string }) {
  const ref = useRef<HTMLDivElement>(null);
  const onCloseRef = useRef(onClose); onCloseRef.current = onClose;
  useEffect(() => { const previous = document.activeElement as HTMLElement; const overflow = document.body.style.overflow; document.body.style.overflow = "hidden"; ref.current?.focus(); const handler = (e: KeyboardEvent) => { if (document.querySelector(".tour-stage[open]")) return; const openDialogs = document.querySelectorAll(".modal-overlay .dialog"); if (openDialogs[openDialogs.length - 1] !== ref.current) return; if (e.key === "Escape") onCloseRef.current(); if (e.key === "Tab") { const nodes = ref.current?.querySelectorAll<HTMLElement>('button:not(:disabled), input:not(:disabled), select:not(:disabled), textarea:not(:disabled), summary, [tabindex="0"]'); if (!nodes?.length) return; const first = nodes[0], last = nodes[nodes.length - 1]; if (e.shiftKey && (document.activeElement === first || document.activeElement === ref.current)) { e.preventDefault(); last.focus(); } else if (!e.shiftKey && (document.activeElement === last || document.activeElement === ref.current)) { e.preventDefault(); first.focus(); } } }; document.addEventListener("keydown", handler); return () => { document.removeEventListener("keydown", handler); document.body.style.overflow = overflow; previous?.focus(); }; }, []);
  return <div className="modal-overlay" onClick={onClose}><div className={`dialog ${className}`} ref={ref} role="dialog" aria-modal="true" aria-label={title} tabIndex={-1} onClick={e => e.stopPropagation()}><div className="section-heading"><h2>{title}</h2><button className="icon-button" aria-label="Cerrar ventana" onClick={onClose}><X size={20} /></button></div>{children}</div></div>;
}
function SupportCard({ title, endpoint, fields, items, onDone, announce, onDelete }: { title: string; endpoint: string; fields: string[]; items: Meta[]; onDone: () => Promise<void>; announce: (text: string, error?: boolean) => void; onDelete: (id: string, label: string) => void }) {
  const [search, setSearch] = useState(""); const [busy, setBusy] = useState(false);
  const visible = items.filter(i => `${i.name || ""} ${i.department || ""} ${i.district || ""}`.toLowerCase().includes(search.toLowerCase()));
  async function submit(e: FormEvent<HTMLFormElement>) { e.preventDefault(); const form = e.currentTarget; const data = Object.fromEntries(new FormData(form)); setBusy(true); try { await request(`/api/metadata/${endpoint}`, post(data)); form.reset(); announce("Dato agregado correctamente."); await onDone(); } catch (err) { announce(err instanceof Error ? err.message : "No se pudo agregar.", true); } finally { setBusy(false); } }
  return <section className="panel support-card" data-tour={`support-${endpoint}`}><div className="section-heading"><h2>{title}</h2><span className="count-badge">{items.length}</span></div><label className="search-box"><Search size={16} /><input aria-label={`Buscar ${title.toLowerCase()}`} value={search} onChange={e => setSearch(e.target.value)} placeholder="Buscar…" /></label><ul className="support-list">{visible.map(i => <li key={i.id}><span className="list-dot" /><span>{i.name || `${i.department} / ${i.district}`}</span><button type="button" className="icon-button danger" aria-label={`Eliminar ${i.name || i.district}`} onClick={() => onDelete(i.id, i.name || `${i.department} / ${i.district}`)}><Trash2 size={15} /></button></li>)}</ul>{!visible.length && <p className="muted">No hay registros para mostrar.</p>}<form className="support-form" onSubmit={submit}>{fields.map(f => <label key={f}>{f === "name" ? "Nombre" : f === "department" ? "Departamento" : "Distrito"}<input name={f} required placeholder={f === "name" ? "Agregar nombre" : f === "department" ? "Ej. Lima" : "Ej. San Isidro"} /></label>)}<button className="btn secondary" disabled={busy}><Plus size={16} />{busy ? "Agregando…" : "Agregar"}</button></form></section>;
}
